  if(d.periodEnd>d.publishedAt||d.publishedAt>d.asOf)throw Error('财报所属期、发布日期与研究截止日不一致');
  if(!['consolidated','parent'].includes(d.statementScope)||!['annual','year-to-date','quarter'].includes(d.periodBasis))throw Error('请明确合并/母公司及年度/累计/单季口径');
  if(d.tolerance!=null&&finite(d.tolerance)<0)throw Error('容差不得为负');
  for(const v of Object.values(d.current||{}))if(v!=null)finite(v);
  if(!Object.values(d.current||{}).some(v=>v!=null))throw Error('至少录入一个财报科目');
  if(d.previous){for(const k of ['previousPeriod','previousPeriodEnd','previousPublishedAt','previousStatementScope','previousPeriodBasis','previousUnit','previousCurrency'])if(!d[k])throw Error('前期资料缺少：'+k);date(d.previousPeriodEnd);date(d.previousPublishedAt);if(d.previousPeriodEnd>=d.periodEnd||d.previousPublishedAt>d.asOf||d.previousPeriodEnd>d.previousPublishedAt||d.previousCurrency!==d.currency)throw Error('前期资料日期或币种不一致');gaps.push('跨期数值未自动判定为同比：仍需核对同一季节和期间长度');}
