function createSession(){return {version:1,revision:0,kind:null,input:null,results:[],changes:[]};}
function revise(session,kind,input,reason){
 if(!session||session.version!==1||!Array.isArray(session.results)||!Array.isArray(session.changes))throw Error('研究会话无效');
 let next=clone(session),same=next.kind===kind&&canonical(next.input)===canonical(input);
 if(same)return next;
 next.revision++;next.kind=kind;next.input=clone(input);
 next.results=next.results.map(r=>({...r,status:'已失效',invalidatedByRevision:next.revision}));
 next.changes.push({revision:next.revision,reason:reason||'输入前提变更',changedAt:new Date().toISOString()});return next;
}
function invalidate(session,reason){let next=clone(session);next.revision++;next.results=next.results.map(r=>({...r,status:'已失效',invalidatedByRevision:next.revision}));next.input=null;next.changes.push({revision:next.revision,reason:reason||'输入已编辑，等待重新计算',changedAt:new Date().toISOString()});return next;}
